  "implementation": "def solve(case):
    if 'threshold' not in case or 'calls' not in case:
        raise ValueError("Missing required keys: threshold, calls")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be a number")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be a list")
    accepted_ids = []
    diagnostics = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("Each call must be a dict")
        for key in ('call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable'):
            if key not in call:
                raise ValueError(f"Missing key {key} in call")
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(tokens, int) or tokens <= 0:
            raise ValueError("prediction_tokens must be positive integer")
        raw_gain = loss_without - loss_with
        normalized = raw_gain / tokens
        accepted = bool(parseable) and (normalized >= threshold)
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": normalized
        })
        if accepted:
            accepted_ids.append(call_id)
    return {
        "accepted_call_ids": accepted_ids,
        "diagnostics": diagnostics
    }"
}
